create table production_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),production_date date not null,shift_template_id uuid not null references shift_templates(id),production_area_id uuid not null references production_areas(id),status text not null default 'draft' check(status in('draft','published','closed')),version integer not null default 1,created_by uuid,published_by uuid,published_at timestamptz,closed_by uuid,closed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,production_date,shift_template_id,production_area_id));
create table production_plan_items(id uuid primary key default gen_random_uuid(),production_plan_id uuid not null references production_plans(id) on delete cascade,production_order_id uuid not null references production_orders(id),order_no text not null,sequence integer not null,planned_units numeric(14,3) not null check(planned_units>0),responsible text,special_instruction text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(production_plan_id,production_order_id),unique(production_plan_id,sequence));
create table production_plan_history(id uuid primary key default gen_random_uuid(),production_plan_id uuid not null references production_plans(id),action text not null,changed_by uuid,changed_by_email text,changed_at timestamptz not null default now(),snapshot jsonb not null);
alter table production_plans enable row level security;alter table production_plan_items enable row level security;alter table production_plan_history enable row level security;revoke all on production_plans,production_plan_items,production_plan_history from anon,authenticated;grant select,insert,update,delete on production_plans,production_plan_items to service_role;grant select,insert on production_plan_history to service_role;
create or replace function create_daily_plan(p_organization_id uuid,p_production_date date,p_shift_id uuid,p_area_id uuid,p_actor_id uuid,p_actor_email text) returns uuid language plpgsql security definer set search_path=public as $$declare result uuid;begin if not exists(select 1 from shift_templates where id=p_shift_id and organization_id=p_organization_id and active)then raise exception 'Invalid shift';end if;if not exists(select 1 from production_areas where id=p_area_id and organization_id=p_organization_id and active and code<>'UNMAPPED')then raise exception 'Invalid area';end if;insert into production_plans(organization_id,production_date,shift_template_id,production_area_id,created_by)values(p_organization_id,p_production_date,p_shift_id,p_area_id,p_actor_id)returning id into result;insert into production_plan_history(production_plan_id,action,changed_by,changed_by_email,snapshot)select result,'created',p_actor_id,p_actor_email,to_jsonb(p)from production_plans p where id=result;return result;end$$;
create or replace function add_daily_plan_items(p_plan_id uuid,p_order_nos text[],p_actor_id uuid,p_actor_email text)returns integer language plpgsql security definer set search_path=public as $$declare p production_plans%rowtype;n text;po production_orders%rowtype;units numeric;seq integer;added integer:=0;begin select*into p from production_plans where id=p_plan_id for update;if p.id is null then raise exception 'Plan not found';end if;if p.status<>'draft'then raise exception 'Only drafts can be edited';end if;select coalesce(max(sequence),0)into seq from production_plan_items where production_plan_id=p_plan_id;foreach n in array p_order_nos loop select*into po from production_orders where organization_id=p.organization_id and order_no=n and planning_status in('planned','ready','in_progress');if po.id is null then raise exception 'Order % is not planned',n;end if;select remaining_units into units from v_production_planning where organization_id=p.organization_id and order_no=n and line=(select code from production_areas where id=p.production_area_id)limit 1;if units is null or units<=0 then raise exception 'Order unavailable in area';end if;seq=seq+1;insert into production_plan_items(production_plan_id,production_order_id,order_no,sequence,planned_units,special_instruction)values(p_plan_id,po.id,n,seq,units,po.special_instruction)on conflict(production_plan_id,production_order_id)do nothing;if found then added=added+1;end if;end loop;insert into production_plan_history(production_plan_id,action,changed_by,changed_by_email,snapshot)values(p_plan_id,'items_added',p_actor_id,p_actor_email,jsonb_build_object('orders',p_order_nos,'added',added));return added;end$$;
create or replace function update_daily_plan_item(p_item_id uuid,p_sequence integer,p_responsible text,p_units numeric,p_actor_id uuid,p_actor_email text)returns void language plpgsql security definer set search_path=public as $$declare pid uuid;stat text;begin select i.production_plan_id,p.status into pid,stat from production_plan_items i join production_plans p on p.id=i.production_plan_id where i.id=p_item_id for update;if stat<>'draft'then raise exception 'Only drafts can be edited';end if;update production_plan_items set sequence=p_sequence,responsible=nullif(trim(p_responsible),''),planned_units=p_units,updated_at=now()where id=p_item_id;insert into production_plan_history(production_plan_id,action,changed_by,changed_by_email,snapshot)select pid,'item_updated',p_actor_id,p_actor_email,to_jsonb(i)from production_plan_items i where id=p_item_id;end$$;
create or replace function transition_daily_plan(p_plan_id uuid,p_action text,p_actor_id uuid,p_actor_email text)returns void language plpgsql security definer set search_path=public as $$declare stat text;items integer;begin select status into stat from production_plans where id=p_plan_id for update;select count(*)into items from production_plan_items where production_plan_id=p_plan_id;if p_action='publish'then if stat<>'draft'or items=0 then raise exception 'Only non-empty drafts can be published';end if;update production_plans set status='published',published_by=p_actor_id,published_at=now(),updated_at=now()where id=p_plan_id;elsif p_action='close'then if stat<>'published'then raise exception 'Only published plans can be closed';end if;update production_plans set status='closed',closed_by=p_actor_id,closed_at=now(),updated_at=now()where id=p_plan_id;else raise exception 'Invalid action';end if;insert into production_plan_history(production_plan_id,action,changed_by,changed_by_email,snapshot)select p_plan_id,p_action,p_actor_id,p_actor_email,to_jsonb(p)from production_plans p where id=p_plan_id;end$$;
revoke all on function create_daily_plan(uuid,date,uuid,uuid,uuid,text),add_daily_plan_items(uuid,text[],uuid,text),update_daily_plan_item(uuid,integer,text,numeric,uuid,text),transition_daily_plan(uuid,text,uuid,text) from public,anon,authenticated;grant execute on function create_daily_plan(uuid,date,uuid,uuid,uuid,text),add_daily_plan_items(uuid,text[],uuid,text),update_daily_plan_item(uuid,integer,text,numeric,uuid,text),transition_daily_plan(uuid,text,uuid,text) to service_role;
create or replace view v_daily_plans with(security_invoker=true)as select p.*,s.name shift_name,a.code area_code,a.name area_name,count(i.id)item_count,coalesce(sum(i.planned_units),0)planned_units from production_plans p join shift_templates s on s.id=p.shift_template_id join production_areas a on a.id=p.production_area_id left join production_plan_items i on i.production_plan_id=p.id group by p.id,s.name,a.code,a.name;revoke all on v_daily_plans from anon,authenticated;grant select on v_daily_plans to service_role;
